"""The stateful pipeline: assign events to windows, aggregate per key, emit on watermark.

Emission is driven by the watermark, not by input order, so the same input produces the same output
regardless of how the lines are grouped. `add` returns whatever closed during that call; `flush`
returns the remainder. Results are always ordered by `(window.start, key)`.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Callable, Iterable

from .errors import ValidationError
from .events import DATA, Event, WatermarkTracker
from .windows import Session, Sliding, Tumbling, Window, merge_sessions

Aggregator = Callable[[list[float]], float]

AGGREGATORS: dict[str, Aggregator] = {
    "count": lambda values: float(len(values)),
    "sum": lambda values: float(sum(values)),
    "min": lambda values: float(min(values)),
    "max": lambda values: float(max(values)),
    "mean": lambda values: float(sum(values) / len(values)),
}


@dataclass(frozen=True, slots=True)
class Result:
    window: Window
    key: str
    aggregation: str
    value: float
    count: int

    def to_document(self) -> dict[str, object]:
        return {
            "window": self.window.to_document(),
            "key": self.key,
            "aggregation": self.aggregation,
            "value": self.value,
            "count": self.count,
        }


@dataclass(slots=True)
class Pipeline:
    windowing: Tumbling | Sliding | Session
    aggregation: str = "sum"
    max_out_of_orderness: int = 0
    allowed_lateness: int = 0
    watermark: WatermarkTracker = field(init=False)
    _values: dict[tuple[int, int, str], list[float]] = field(default_factory=dict, init=False)
    _emitted: set[tuple[int, int, str]] = field(default_factory=set, init=False)

    def __post_init__(self) -> None:
        if self.aggregation not in AGGREGATORS:
            raise ValidationError(f"unknown aggregation: {self.aggregation}", known=sorted(AGGREGATORS))
        if self.allowed_lateness < 0:
            raise ValidationError("allowed_lateness must be >= 0", value=self.allowed_lateness)
        self.watermark = WatermarkTracker(max_out_of_orderness=self.max_out_of_orderness)

    # -- input ---------------------------------------------------------------
    def add(self, event: Event) -> list[Result]:
        if event.kind != DATA:
            self.watermark.advance_to(event.timestamp)
            return self._emit(force_end=None)
        if self.watermark.observe(event.timestamp):
            return []  # late: counted by the tracker, never applied to a closed window
        for window in self._windows_for(event.timestamp):
            self._values.setdefault((window.start, window.end, event.key), []).append(event.value)
        return self._emit(force_end=None)

    def run(self, events: Iterable[Event]) -> list[Result]:
        results: list[Result] = []
        for event in events:
            results.extend(self.add(event))
        results.extend(self.flush())
        return results

    def flush(self) -> list[Result]:
        return self._emit(force_end=True)

    # -- internals -----------------------------------------------------------
    def _windows_for(self, timestamp: int) -> list[Window]:
        if isinstance(self.windowing, Session):
            return self.windowing.assign(timestamp)
        return self.windowing.assign(timestamp)

    def _emit(self, force_end: bool | None) -> list[Result]:
        if isinstance(self.windowing, Session):
            return self._emit_sessions(force_end)
        results: list[Result] = []
        for key in sorted(self._values):
            start, end, aggregation_key = key
            if key in self._emitted:
                continue
            closed = force_end or self.watermark.is_closed(end + self.allowed_lateness)
            if not closed:
                continue
            results.append(self._result(start, end, aggregation_key))
            self._emitted.add(key)
        return sorted(results, key=lambda result: (result.window.start, result.key))

    def _emit_sessions(self, force_end: bool | None) -> list[Result]:
        results: list[Result] = []
        gap = self.windowing.gap
        for aggregation_key in sorted({key[2] for key in self._values}):
            windows = [Window(key[0], key[1]) for key in self._values if key[2] == aggregation_key]
            merged = merge_sessions(windows, gap)
            for window in merged:
                values: list[float] = []
                for key, stored in self._values.items():
                    if key[2] != aggregation_key:
                        continue
                    if window.start <= key[0] and key[1] <= window.end:
                        values.extend(stored)
                identity = (window.start, window.end, aggregation_key)
                if identity in self._emitted or not values:
                    continue
                closed = force_end or self.watermark.is_closed(window.end + gap + self.allowed_lateness)
                if not closed:
                    continue
                results.append(self._result(window.start, window.end, aggregation_key, values))
                self._emitted.add(identity)
        return sorted(results, key=lambda result: (result.window.start, result.key))

    def _result(self, start: int, end: int, key: str, values: list[float] | None = None) -> Result:
        stored = values if values is not None else self._values[(start, end, key)]
        return Result(
            window=Window(start, end),
            key=key,
            aggregation=self.aggregation,
            value=AGGREGATORS[self.aggregation](stored),
            count=len(stored),
        )

"""Window assignment: tumbling, sliding and session windows over event time.

Every assigner answers one question: for an event at timestamp `t`, which half-open windows
`[start, end)` does it belong to? Session windows are the exception -- they grow by merging, so they
expose `assign_session` instead of a fixed list.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable, Sequence

from .errors import ValidationError, WindowError


@dataclass(frozen=True, slots=True, order=True)
class Window:
    start: int
    end: int

    def __post_init__(self) -> None:
        if self.end <= self.start:
            raise WindowError("window end must be greater than start", start=self.start, end=self.end)

    @property
    def size(self) -> int:
        return self.end - self.start

    def contains(self, timestamp: int) -> bool:
        return self.start <= timestamp < self.end

    def to_document(self) -> dict[str, int]:
        return {"start": self.start, "end": self.end}


@dataclass(frozen=True, slots=True)
class Tumbling:
    """Fixed, non-overlapping windows of `size` ms, aligned to `offset`."""

    size: int
    offset: int = 0

    def __post_init__(self) -> None:
        if self.size <= 0:
            raise ValidationError("tumbling size must be > 0", value=self.size)

    def assign(self, timestamp: int) -> list[Window]:
        start = self.offset + ((timestamp - self.offset) // self.size) * self.size
        return [Window(start, start + self.size)]

    def boundaries(self, first: int, last: int) -> list[Window]:
        """Every window that intersects `[first, last]`, in ascending order."""
        if last < first:
            raise ValidationError("last must be >= first", first=first, last=last)
        first_start = self.assign(first)[0].start
        windows: list[Window] = []
        start = first_start
        while start <= last:
            windows.append(Window(start, start + self.size))
            start += self.size
        return windows


@dataclass(frozen=True, slots=True)
class Sliding:
    """Windows of `size` ms starting every `slide` ms; overlapping when slide < size."""

    size: int
    slide: int
    offset: int = 0

    def __post_init__(self) -> None:
        if self.size <= 0:
            raise ValidationError("sliding size must be > 0", value=self.size)
        if self.slide <= 0:
            raise ValidationError("sliding slide must be > 0", value=self.slide)

    def assign(self, timestamp: int) -> list[Window]:
        latest = self.offset + ((timestamp - self.offset) // self.slide) * self.slide
        starts = [latest - index * self.slide for index in range((self.size + self.slide - 1) // self.slide)]
        return [Window(start, start + self.size) for start in sorted(starts) if start <= timestamp < start + self.size]


@dataclass(frozen=True, slots=True)
class Session:
    """Gap-based windows: events closer than `gap` ms share one window that keeps growing."""

    gap: int

    def __post_init__(self) -> None:
        if self.gap <= 0:
            raise ValidationError("session gap must be > 0", value=self.gap)

    def assign(self, timestamp: int) -> list[Window]:
        return [Window(timestamp, timestamp + 1)]


def merge_sessions(windows: Iterable[Window], gap: int) -> list[Window]:
    """Merge windows whose gap is at most `gap`, in ascending order."""
    if gap <= 0:
        raise ValidationError("session gap must be > 0", value=gap)
    ordered: Sequence[Window] = sorted(windows)
    merged: list[Window] = []
    for window in ordered:
        if merged and window.start - merged[-1].end <= gap:
            previous = merged[-1]
            merged[-1] = Window(previous.start, max(previous.end, window.end))
        else:
            merged.append(window)
    return merged


def tumbling(size: int, offset: int = 0) -> Tumbling:
    return Tumbling(size, offset)


def sliding(size: int, slide: int, offset: int = 0) -> Sliding:
    return Sliding(size, slide, offset)


def session(gap: int) -> Session:
    return Session(gap)

"""Event model and watermark tracking.

Timestamps are integer milliseconds since the epoch. An event carries a `key`, a numeric `value`,
and a `kind` which is either `data` (counted by aggregations) or `punct` (a punctuation marker that
advances time without contributing a value). Keeping `punct` explicit means a stream can express
"no more data before T" without inventing a fake value.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from typing import Any, Iterable, Iterator

from .errors import ParseError, ValidationError

DATA = "data"
PUNCT = "punct"
KINDS = (DATA, PUNCT)


@dataclass(frozen=True, slots=True)
class Event:
    timestamp: int
    key: str
    value: float = 0.0
    kind: str = DATA

    def to_document(self) -> dict[str, Any]:
        return {"timestamp": self.timestamp, "key": self.key, "value": self.value, "kind": self.kind}


@dataclass(slots=True)
class WatermarkTracker:
    """Tracks how far time has provably advanced.

    The watermark is `max_seen - max_out_of_orderness`. An event whose timestamp is below the
    current watermark is *late*: by default it is counted and dropped, never silently applied to a
    window that was already emitted.
    """

    max_out_of_orderness: int = 0
    _max_seen: int | None = None
    late_dropped: int = field(default=0, init=False)
    observed: int = field(default=0, init=False)

    def __post_init__(self) -> None:
        if self.max_out_of_orderness < 0:
            raise ValidationError("max_out_of_orderness must be >= 0", value=self.max_out_of_orderness)

    @property
    def max_seen(self) -> int | None:
        return self._max_seen

    @property
    def current(self) -> int | None:
        if self._max_seen is None:
            return None
        return self._max_seen - self.max_out_of_orderness

    def observe(self, timestamp: int) -> bool:
        """Record a timestamp; return True when it is late (below the current watermark)."""
        current = self.current
        late = current is not None and timestamp < current
        self.observed += 1
        if late:
            self.late_dropped += 1
        if self._max_seen is None or timestamp > self._max_seen:
            self._max_seen = timestamp
        return late

    def advance_to(self, timestamp: int) -> None:
        """Punctuation: time itself has advanced to `timestamp`."""
        if self._max_seen is None or timestamp > self._max_seen:
            self._max_seen = timestamp

    def is_closed(self, end: int) -> bool:
        """A window ending at `end` (exclusive) may emit once the watermark reaches `end`."""
        current = self.current
        return current is not None and current >= end


def parse_event_line(text: str, *, line: int | None = None) -> Event:
    """Parse one JSON object into an Event, reporting a position on every failure."""
    stripped = text.strip()
    if not stripped:
        raise ParseError("empty line", line=line, column=1)
    try:
        document = json.loads(stripped)
    except json.JSONDecodeError as error:
        raise ParseError(f"invalid JSON: {error.msg}", line=line, column=error.colno) from error
    if not isinstance(document, dict):
        raise ParseError("event must be a JSON object", line=line, column=1)
    unknown = sorted(set(document) - {"timestamp", "key", "value", "kind"})
    if unknown:
        raise ParseError(f"unknown field(s): {', '.join(unknown)}", line=line, column=1)
    if "timestamp" not in document:
        raise ParseError("missing field: timestamp", line=line, column=1)
    if "key" not in document:
        raise ParseError("missing field: key", line=line, column=1)
    timestamp = document["timestamp"]
    if isinstance(timestamp, bool) or not isinstance(timestamp, int):
        raise ParseError("timestamp must be an integer (milliseconds)", line=line, column=1)
    key = document["key"]
    if not isinstance(key, str) or not key:
        raise ParseError("key must be a non-empty string", line=line, column=1)
    value = document.get("value", 0.0)
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ParseError("value must be a number", line=line, column=1)
    kind = document.get("kind", DATA)
    if kind not in KINDS:
        raise ParseError(f"kind must be one of {', '.join(KINDS)}", line=line, column=1)
    return Event(timestamp=timestamp, key=key, value=float(value), kind=kind)


def parse_event_lines(lines: Iterable[str]) -> Iterator[Event]:
    for number, text in enumerate(lines, start=1):
        yield parse_event_line(text, line=number)

